-- Templates live in the database. Header and footer are sections, not site settings.

alter table public.site drop constraint site_preset_check;
alter table public.site drop constraint site_document_object;
alter table public.site_draft drop constraint site_draft_document_object;
alter table public.site_revision drop constraint site_revision_document_object;

create function public.upgrade_site_document_v2(doc jsonb)
returns jsonb
language sql
immutable
as $$
  select case
    when doc->>'schemaVersion' = '2' then doc
    else jsonb_strip_nulls(jsonb_build_object(
      'schemaVersion', 2,
      'businessName', doc->'businessName',
      'theme', doc->'theme',
      'booking', doc->'booking',
      'sections',
        jsonb_build_array(jsonb_build_object(
          'id', 'site-header',
          'type', 'headerMenu',
          'props', jsonb_build_object('links', coalesce(doc->'nav'->'links', '[]'::jsonb))
        )) || coalesce(doc->'sections', '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
          'id', 'site-footer',
          'type', 'footerSimple',
          'props', jsonb_build_object('text', coalesce(doc->'footer'->>'text', 'Footer'))
        )),
      'seo', doc->'seo'
    ))
  end;
$$;

update public.site set document = public.upgrade_site_document_v2(document);
update public.site_draft set document = public.upgrade_site_document_v2(document);
update public.site_revision set document = public.upgrade_site_document_v2(document);

drop function public.upgrade_site_document_v2(jsonb);

alter table public.site add constraint site_document_object check (
  jsonb_typeof(document) = 'object'
  and document->>'schemaVersion' = '2'
);

alter table public.site_draft add constraint site_draft_document_object check (
  jsonb_typeof(document) = 'object'
  and document->>'schemaVersion' = '2'
);

alter table public.site_revision add constraint site_revision_document_object check (
  jsonb_typeof(document) = 'object'
  and document->>'schemaVersion' = '2'
);

create table public.site_template (
  id text primary key,
  name text not null,
  document jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint site_template_id_format check (id ~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$'),
  constraint site_template_name_length check (char_length(name) between 1 and 80),
  constraint site_template_document_object check (
    jsonb_typeof(document) = 'object'
    and document->>'schemaVersion' = '2'
  )
);

comment on table public.site_template is
  'Admin-only starting page. Header and footer, when present, are sections inside document.';

create trigger site_template_set_updated_at
  before update on public.site_template
  for each row execute function extensions.moddatetime('updated_at');

alter table public.site_template enable row level security;

revoke all on table public.site_template from public, anon, authenticated;
grant all on table public.site_template to service_role;

